export function workoutPage(){
 // 2026-11-27 대표님(2안, 식단 페이지와 같은 틀): 날짜 가운데 → 오늘 운동 요약(세트·부위·이번 주 운동한 날·쉬어 가기 안내) → 운동 흐름 → 한 운동(누르면 세트가 그 자리에서) → 종목 성장 → 더 보기. 운동 일지(지난 날짜들)는 더 보기로.
 const rm=$s.selectedDate===$f.today()?returnMode(actualDB($s.db),$f.today()):null,g=$s.db.settings.weeklyWorkoutGoal||3;
 return `<div class="page-head"><div><span class="eyebrow">Workout</span><h2>운동 기록</h2></div><button class="button" data-modal="workout">＋ 운동</button></div><div class="wd-datebar">${$f.dateBar('workout')}</div>${liveCardHTML($f.liveState(),$s.db)}${returnNoteHTML(rm,g)}${$s.weekGoalOpen?`<div class="chip-row week-goal-pick" role="group" aria-label="주간 운동 횟수">${[1,2,3,4,5,6,7].map(n=>`<button type="button" class="chip${($s.db.settings.weeklyWorkoutGoal||3)===n?' active':''}" data-week-goal-set="${n}">주 ${n}회</button>`).join('')}</div>`:''}${workoutDayHTML($s.db,$s.selectedDate,{today:$f.today(),goal:returnGoal(g,rm),open:$s.wpOpen||'',weight:$s.latestWeight(),burn:workoutBurn,findMachine:id=>findMachine($s.db,$s.sharedCatalog,id)})}${sessionControlsIf()}${$s.guideRun&&$s.guideRun.phase!=='done'?`<section class="section card guide-resume"><h3>운동 안내 진행 중</h3><p class="hint">${$s.esc(guideCurrent($s.guideRun)?.name||'')} · ${$s.guideRun.set}세트${$s.guideRun.phase==='rest'?' · 휴식 중':''}</p><button class="button" data-modal="workout">안내로 돌아가기</button></section>`:''}${workoutGrowthHTML($s.db,{end:$s.selectedDate})}${moreTilesHTML(pageSecs('workout'))}`
}
// 운동 일지(지난 날짜들): 더 보기 타일 안에서 전부
function workoutLogHTML(){
 const list=$s.recent($s.db.workouts).filter(w=>!w.planned),row=w=>{if(w.rest)return `<div class="record rest-record"><div><strong>${$s.esc(w.date)} · 🌙 의도적 휴식</strong><small>쉬는 것도 계획의 일부예요</small></div><div class="record-actions"><button data-delete="workouts:${$s.esc(w.id)}" aria-label="휴식 기록 지우기">지우기</button></div></div>`;if(w.recalled)return `<div class="record"><div><strong>${$s.esc(w.date)} · ${$s.esc(workoutTitle(w))}</strong><small>기억나는 만큼 적은 운동 · 종목·세트는 비어 있어요</small></div><div class="record-actions"><button data-detail="${$s.esc(w.id)}">보기</button><button data-delete="workouts:${$s.esc(w.id)}" aria-label="기록 지우기">지우기</button></div></div>`;const t=workoutTotals(w);return `<div class="record diary-row"><div class="diary-art">${(w.exercises||[]).slice(0,3).map(e=>exArtHTML(e,'ex-art-sm',{fallback:true})).join('')}</div><div><strong>${$s.esc(w.date)} · ${$s.esc(workoutTitle(w))}${w.importBatch?' <em class="imp-tag">가져온 기록</em>':''}</strong><small>${$f.diaryLine(w,t)}${(b=>b?.kcal!=null&&!w.planned?` · 약 ${$s.fmt(b.kcal,0)}kcal 소모`:'')(workoutBurn(w,$s.latestWeight()))}</small></div><div class="record-actions"><button data-reload="${$s.esc(w.id)}">복사</button><button data-detail="${$s.esc(w.id)}">보기</button>${workoutMenuHTML(w,$s.db)}</div></div>`};
 return `<section class="section"><div class="card">${list.length?list.map(row).join(''):emptyArt('workout','첫 운동을 기록해 보세요.')}</div></section>`
}
function sessionControlsIf(){return $s.savedDraft?sessionControls():''}
