function settingsSections(){
 const admin=!!(adminPlanCardHTML($s.esc,{serverInfo:$s.aiMe,aiConnected:aiConnected()})||accountAdminHTML($s.adminJust)||isCatalogAdmin(cloudState.user));
 const coach=`${$s.coach.settingsTop()}${$s.coach.settingsMember()}`;
 return [
  ['account','account','계정·마이태그',cloudState.user?'로그인·동기화·마이태그·계정 삭제':'로그인하고 기록을 서버에 보관',()=>`${cloudSettingsHTML()}${mytagSettingsHTML()}${deleteAccountHTML()}`],
  ['record','record','기록 항목·목표','무엇을 기록할지, 식단 목표, 목표 페이즈',()=>`${prefsSettingsHTML($s.db)}${goalSummaryHTML($s.db.settings)}${phaseSettingsHTML($s.db,$f.today())}`],
  ['screen','screen','화면','어두운 화면·밝은 화면',()=>`<section class="section card theme-card"><h3>화면 모드</h3><p class="hint">지금 화면은 어두운 모드예요. 밝은 화면은 시험 중이라 일부 색이 다르게 보일 수 있어요.</p><div class="chip-row">${[['dark','어두운 화면'],['light','밝은 화면 (시험)']].map(([k,l])=>`<button type="button" class="chip ${$s.themePref()===k?'active':''}" data-theme-set="${k}">${l}</button>`).join('')}</div></section>`],
  ['bell','bell','알림','기록 알림 시각',()=>reminderSettingsHTML($s.db)],
  ['gym','gym','운동 장소','다니는 헬스장·머신',()=>$f.gymSettingsHTML()],
  /* 2026-11-27 대표님: 헬스장 둘러보기(기구가 등록된 헬스장·비치 기구) */['gymbrowse','pin','헬스장 둘러보기','주변·이름으로 찾고 비치 기구 보기',()=>$s.gymBrowse?.open?gymDetailHTML($s.gymBrowse.open,$s.sharedCatalog,{admin:isCatalogAdmin(cloudState.user)}):gymBrowseHTML($s.gymBrowse||{},$s.sharedCatalog,$s.db.settings,{signedIn:cloudState.approval==='approved'})],
  ['ai','ai','AI 연결','내 AI 연결·AI 입력 방식',()=>aiSettingsHTML()],
  ['health','health','건강 앱 연동','삼성 헬스·헬스 커넥트 걸음·체중',()=>healthSettingsHTML({native:!!healthPlugin(),status:$s.hc?.status,granted:$s.hc?.granted,auto:!!$s.db.settings?.healthAuto})],
  ['import','backup','다른 곳 기록 가져오기','예전 기록·다른 앱 기록을 날짜별로 한 번에',()=>importPageHTML($s.db,$s.impSt||{})],
  ['backup','backup','백업·복원','기록 파일로 저장·되살리기',()=>`<section class="section card"><h3>백업과 복원</h3><p class="small muted">기록 전체를 파일로 저장해 두세요. 복원은 지금 기록을 바꿔 씁니다.</p><div class="actions"><button class="button secondary" id="export">기록 파일 저장</button><button class="button secondary" data-modal="restore">기록 파일 복원</button></div></section><section class="section card"><h3>임시 운동 기록</h3><p class="hint">운동 중인 기록은 이 기기에 임시 저장돼요.</p><div class="actions"><button class="button secondary" id="draft-export">임시 운동 기록 내보내기</button><button class="button secondary" id="draft-archive-export">지난 운동 초안 내보내기</button></div></section>`],
  ['trash','trash','휴지통','지운 기록 되살리기',()=>trashHTML(readTrash($s.TRASH()))],
  ['book','book','음식·운동 도감','내 음식·내 종목, 도감 요청',()=>catalogSettingsHTML()],
  ...(coach.trim()?[['coach','coach','코치','코치로그 연결·회원',()=>coach]]:[]),
  ['help','help','도움말·소개','자주 묻는 질문, 마이로그 이야기',()=>`<section class="section card help-entry"><div><h3>도움말</h3><p class="hint">자주 묻는 질문을 모아 두었어요.</p></div><button type="button" class="button secondary" data-modal="help">도움말 보기</button></section><a class="section card story-link" href="story.html"><span class="story-word">My<b>logue</b></span><span class="story-text"><b>마이로그 이야기</b><small>기록(log)이 모이면 이야기(logue)가 됩니다</small></span><span aria-hidden="true">›</span></a>${cloudState.user?'':'<button type="button" class="section card story-link landing-again" id="landing-view"><span class="story-word">처음</span><span class="story-text"><b>첫 화면 다시 보기</b><small>마이로그 소개와 예시 기록</small></span><span aria-hidden="true">›</span></button>'}`],
  ...(admin?[['admin','admin','관리자','가입자·플러스·코치 권한, AI 비용, 도감',()=>`${adminPlanCardHTML($s.esc,{serverInfo:$s.aiMe,aiConnected:aiConnected()})}${accountAdminHTML($s.adminJust)}${isCatalogAdmin(cloudState.user)?promoteHTML(promoteCandidates($s.db,{sharedFoods:$s.sharedCatalog.foods||[],sharedExercises:$s.sharedCatalog.exercises||[],baseExercises:PROMOTE_BASE_EX}),$s.esc,$s.promotePicked||null):''}`]]:[]),
 ];
}
export function settingsSectionHTML(key){const x=settingsSections().find(s=>s[0]===key);return x?{title:x[2],html:`<div class="set-pop">${x[4]()}</div>`}:null}
export function settingsPage(){const list=settingsSections();/* 5.4.2 코치로그면 코치 설정을 맨 위에(수업 계획 보내기·출석 확인·결제 금액·코멘트) */const coachTop=(()=>{try{return $s.coach?.settingsTop?.()||''}catch{return ''}})();return `${coachTop?`<div class="coach-head2"><div><h2>코치 설정</h2></div></div>${coachTop}<h3 class="section-title" style="margin-top:22px">마이로그 설정</h3>`:''}<div class="page-head"${coachTop?' hidden':''}><div><span class="eyebrow">Settings</span><h2>설정</h2><p>필요한 것을 눌러 바꿔요.</p>${$f.storageNoteHTML()}</div></div><div class="set-grid set-main">${list.map(([key,ic,title,desc],i)=>`<button type="button" class="set-tile" data-set-sec="${key}" style="--i:${i%6}" title="${$s.esc(desc)}"><b class="set-ic"><svg viewBox="0 0 24 24" aria-hidden="true">${SET_ICON[ic]}</svg></b><span class="set-txt"><strong>${title==='다른 곳 기록 가져오기'?'기록 가져오기':title}</strong></span></button>`).join('')}</div><p class="hint app-version">마이로그 베타 ${$s.esc(APP_VERSION)}</p>`}
export function calendarPage(){/* 2026-11-27 대표님(일정 1단계): 달력 맨 위·그날 보기·다가오는 일·요일별 운동 계획(schedule-plan.js) */const coach=$s.coach.memberSchedule($s.selectedDate).map(x=>`<section class="section card coach-booked"><b>${$s.esc(String(x.startAt).slice(11,16))} · ${$s.esc(x.title||'수업')}</b><small>${$s.esc(x.trainerName||'코치')} 코치님 예약${x.place?` · ${$s.esc(x.place)}`:''} · ${x.durationMin||50}분</small></section>`).join('');return schedulePageHTML($s.db,$s.selectedDate,$f.today(),{coachHTML:coach})}
export function foodPage(){/* 5.0.4 대표님: 요약 → 식단 흐름 → 먹은 것(끼니마다 한 줄) → 맨 아래 더 보기 타일 */return renderFoodPage($s.db,$s.selectedDate,{...$f.homePlanOpts($s.selectedDate),openMacro:$s.macroOpen||'',dateBar:$f.dateBar('food'),checkHtml:foodCheckHTML($s.db),openMeal:$s.mealOpen||null,tiles:moreTilesHTML(pageSecs('food')),trendHtml:dietFlowHTML($s.db,{metric:$s.dfMetric,period:$s.dfPeriod,end:$s.selectedDate})})}
export function home(){const pf=prefsOf($s.db);return `${liveCardHTML($f.liveState(),$s.db)}${(()=>{try{return $s.coach?.memberHomeHTML?.(($s.aiDrafts||[]).filter(d=>d.sourceModel==='trainer'&&(!d.status||d.status==='pending')).length,($s.db.workouts||[]).filter(w=>String(w.sourceDraftId||'').startsWith('t-')).sort((a,b)=>String(b.date).localeCompare(String(a.date)))[0]||null)||''}catch{return ''}})()}${$f.botCard()}${coachNote()}${cloudState.user&&!pf.onboarded&&$s.onbChecked&&$s.modal!=='onboarding'?`<section class="section card onb-card"><h3>나에게 맞추기</h3><p class="hint">질문 몇 개로 기록 방식을 내게 맞게 정해요. 30초면 끝나요.</p><div class="actions"><button class="button" id="onb-start">맞추기 시작</button><button class="button secondary" id="onb-dismiss">괜찮아요</button></div></section>`:''}${renderHomeTimeline($s.db,$s.selectedDate,{...$f.homePlanOpts($s.selectedDate),dateBar:$f.dateBar('home'),isToday:$s.selectedDate===$f.today(),motivHtml:'',voiceHtml:$s.selectedDate===$f.today()?(()=>{try{const a=actualDB($s.db);return voiceHTML(homeVoice(a,$f.today()),phaseBadgeHTML(phaseStatus(a,$f.today())))}catch{return ''}})():''})}${$f.pendingNoteHTML()}${backupNudgeHTML()}${/* 5.3.0 전수 검사: 검토할 초안이 있을 때만 */($s.aiDrafts||[]).filter(d=>!d.status||d.status==='pending').length?`<section class="section card ai-entry-card"><h3>AI가 작성한 기록 <small>${($s.aiDrafts||[]).filter(d=>!d.status||d.status==='pending').length}건 기다려요</small></h3><p class="hint">사진이나 말로 부탁한 기록은 검토함에서 확인한 뒤 저장하세요.</p><button class="button secondary" data-page="ai-inbox">AI 검토함 열기</button></section>`:''}`}
export function aiSettingsHTML(){
 const st=$s.aiBridge.status,mine=st?.paired&&st.uid===cloudState.user?.uid,other=st?.paired&&!mine;
 const badge=mine?'<span class="status-badge ok">✓ 연결됨</span>':st?'<span class="status-badge wait">연결 전</span>':'<span class="status-badge info">도구 꺼짐</span>';
 let body;
 if(!cloudState.user)body='<p class="hint">로그인한 뒤 AI 도구를 연결할 수 있어요.</p>';
 else if($s.aiBridge.checking&&!$s.aiBridge.checked)body='<p class="hint">이 PC의 AI 도구를 찾는 중…</p>';
 else if(mine)body=`<div class="ai-connected"><b>이 PC의 AI 도구와 연결돼 있어요</b><span>${st.persistent?'이 PC에서는 계속 연결돼요. 도구를 다시 켜도 자동으로 이어져요.':'연결이 곧 만료돼요. 다시 연결하면 계속 유지돼요.'}</span><small>AI가 쓴 초안은 ‘AI 검토함’에 쌓이고, 확인한 것만 내 기록이 돼요.</small></div><div class="actions"><button type="button" class="button secondary" data-page="ai-inbox">AI 검토함 열기</button><button type="button" class="text-button" id="ai-unpair">이 PC 연결 해제</button></div>`;
 else if(cloudState.native)body='<p class="hint">휴대전화에서는 AI 도구와 연결하지 않아요. 연결은 AI 도구가 있는 PC의 브라우저에서 해 주세요. 연결한 뒤에는 휴대전화에서도 검토함을 볼 수 있어요.</p><div class="actions"><button type="button" class="button secondary" data-page="ai-inbox">AI 검토함 열기</button></div>';
 else if(st?.outdated)body='<p>이 PC의 마이로그 도구가 예전 버전이에요.</p><p class="hint">보안을 위해 새 버전(연결 코드 방식)으로 바꾼 뒤 연결할 수 있어요. AI 앱에 등록한 agent-bridge 폴더를 최신으로 바꾸고 도구를 다시 켜 주세요.</p>';
 else if(st)body=`<p>${other?'이 PC의 AI 도구가 다른 계정에 연결돼 있어요. 코드를 넣으면 지금 계정으로 바꿔요.':'이 PC에서 AI 도구가 켜져 있어요. 연결 코드를 넣으면 연결돼요.'}</p><form id="ai-pair-form" class="ai-pair-form"><label class="field">연결 코드<input id="ai-pair-code" name="code" autocomplete="off" autocapitalize="characters" spellcheck="false" maxlength="11" placeholder="ABCDE-FGHJK" required></label><button class="button wide" id="ai-pair-now">이 PC의 AI 도구와 연결</button></form><p class="hint">코드는 AI에게 “마이로그 연결 코드 알려줘”라고 물으면 알려 줘요. 코드가 맞는 진짜 도구에만 로그인 정보를 보내요. 한 번 연결하면 이 PC에서는 계속 유지돼요.</p>`;
 else body=`<p>이 PC에서 AI 도구를 찾지 못했어요.</p><ol class="ai-steps"><li>Codex·Claude 같은 AI 앱에 마이로그 도구(agent-bridge)를 등록해 켜 두세요.</li><li>이 화면에서 ‘다시 찾기’를 누르면 연결 버튼이 나와요.</li></ol><div class="actions"><button type="button" class="button secondary" id="ai-bridge-check">${$s.aiBridge.checking?'찾는 중…':'다시 찾기'}</button></div><p class="hint">휴대전화에서는 연결할 수 없어요. 연결은 AI 도구가 있는 PC의 브라우저에서 해 주세요. 연결한 뒤에는 휴대전화에서도 검토함과 알림을 볼 수 있어요.</p>`;
 return `<section class="section card ai-pair-card${mine?' connected':''}" id="ai-connect"><h3>내 AI 연결 ${badge}</h3><p class="hint ai-mode-line">‘AI로 입력’을 누를 때 열리는 방식은 ${changeModeButton()}에서 고를 수 있어요.</p>${body}<details class="ai-advanced"><summary>고급: 포트 바꾸기</summary><form id="ai-port-form" class="actions"><input name="port" type="number" min="1024" max="65535" inputmode="numeric" value="${$s.esc($s.aiBridge.port)}" aria-label="AI 도구 포트"><button class="button secondary">이 포트로 찾기</button></form><p class="hint">기본 포트는 ${BRIDGE_PORT}이에요. 다른 프로그램이 쓰고 있으면 도구가 알려 주는 포트를 넣어 주세요.</p></details></section>`;
}
export function catalogSettingsHTML(){const admin=isCatalogAdmin(cloudState.user);return `${myBookHTML()}<section class="section card catalog-panel"><h3>음식·운동 등록</h3><p class="hint">내가 직접 입력한 음식·머신은 내 기록에 보관됩니다. 기록 이용 승인 후 계정 서버와 동기화합니다. 공용 도감 등록은 관리자 검토 후 적용됩니다.</p><div class="actions"><button type="button" class="button secondary" data-modal="batch-detail">음식 직접 입력</button><button type="button" class="button secondary" data-modal="catalog-request">공용 등록 요청</button>${admin?'<button type="button" class="button secondary" data-modal="catalog-admin-food">공용 음식 편집</button>':''}</div><p class="hint">${$s.esc($s.autoSyncStatus||(!cloudState.user?'로그인 전 · 이 기기에만 저장':'서버 연결 확인 중'))}${$s.sharedCatalog.error?`<br>공용 도감: ${$s.esc($s.sharedCatalog.error)}`:''}${$s.catalogRequestError?`<br>등록 요청: ${$s.esc($s.catalogRequestError)}`:''}</p>${cloudState.user?`<h4 id="catalog-requests">${admin?'전체 등록 요청':'내 등록 요청'}</h4>${admin&&$s.catalogRequests.some(r=>(r.status==='pending'||r.status==='in_review')&&parseGymRequest(r.note))?`<button type="button" class="button secondary" id="gm-approve-all">헬스장 머신 요청 모두 승인 (${$s.catalogRequests.filter(r=>(r.status==='pending'||r.status==='in_review')&&parseGymRequest(r.note)).length}개)</button>`:''}${$s.catalogRequests.map(requestRowHTML).join('')||'<p class="hint">등록 요청이 없습니다.</p>'}`:'<p class="hint">등록 요청과 공용 도감은 로그인 후 사용할 수 있습니다.</p>'}</section>`}
export function catalogRequestHTML(){return `<form id="catalog-request-form" class="gap"><p class="hint">머신 사진 요청은 기계 전체와 제조사·모델 명판을 각각 촬영해 올려주세요. 사람 얼굴·회원 정보가 찍히지 않게 해주세요. 두 사진은 작게 압축되어 승인된 본인과 관리자만 볼 수 있는 서버 요청함에 보관됩니다.</p><label class="field">요청 종류<select name="type"><option value="machine">머신·장비</option><option value="exercise">운동 종목</option><option value="food">음식</option></select></label><label class="field">등록 방식<select name="mode"><option value="manual">직접 입력</option><option value="photo">사진으로 머신 요청</option></select></label><div class="form-grid" data-photo-fields hidden><label class="field">머신 전체 사진<input name="wholePhoto" type="file" accept="image/jpeg,image/png,image/webp"></label><label class="field">제조사·모델 명판 사진<input name="nameplatePhoto" type="file" accept="image/jpeg,image/png,image/webp"></label></div><p class="hint">사진 방식은 머신 요청에서만 선택할 수 있고 두 장 모두 필요합니다. 직접 입력 방식에서는 사진을 보내지 않습니다.</p><label class="field">음식·운동 이름<input name="name" placeholder="예: 제로핵 베이글 / V스쿼트"></label><label class="field">제조사<input name="manufacturer" placeholder="예: 해머스트렝스"></label><label class="field">머신 모델<input name="model" placeholder="모델명 또는 번호"></label><label class="field">헬스장·지점<input name="gymName" placeholder="예: 헬스플러스 안산점"></label><fieldset class="card"><legend>예상 타깃 · 선택</legend><div class="chip-row">${Object.entries(MUSCLE_LABELS).map(([id,label])=>`<label class="chip"><input type="checkbox" name="targetIds" value="${$s.esc(id)}"> ${$s.esc(label)}</label>`).join('')}</div></fieldset><div class="form-grid nutrient-fields">${[['servingQty','기준량 (음식)'],['calories','칼로리 kcal'],['carbs','탄수화물 g'],['protein','단백질 g'],['fat','지방 g']].map(([key,label])=>`<label class="field">${label}<input name="${key}" type="number" min="0" step="any"></label>`).join('')}</div><label class="field">음식 기준 단위<select name="servingUnit"><option value="g">g</option><option value="개">개</option><option value="회">회</option></select></label><label class="field">추가 정보<textarea name="note" rows="3" placeholder="제품 라벨, 운동 방식, 머신 특징 등"></textarea></label><button type="submit" class="button">관리자에게 등록 요청</button></form>`}
export function catalogAdminFoodHTML(){const food=$s.catalogAdminFood||{},items=$f.catalogFoods();return `<div class="gap"><p class="hint">코드 기본값과 서버 수정값을 합쳐 보여줍니다. 저장한 서버 수치가 이후 기록에 적용됩니다. 이전 식사 기록은 유지됩니다.</p><div class="chip-row">${items.map(x=>`<button type="button" class="chip" data-admin-food="${$s.esc(x.id)}">${$s.esc(x.name)}</button>`).join('')}</div><button type="button" class="text-button" id="admin-food-new">＋ 공용 음식 추가</button><form id="catalog-admin-food-form" class="gap"><input name="id" type="hidden" value="${$s.esc(food.id||'')}"><label class="field">음식 이름<input name="name" required value="${$s.esc(food.name||'')}"></label><div class="form-grid"><label class="field">기준량<input name="servingQty" type="number" min="0.01" step="any" required value="${$s.esc(food.servingQty||100)}"></label><label class="field">단위<select name="servingUnit">${(l=>food.servingUnit&&!l.includes(food.servingUnit)?[food.servingUnit,...l]:l)(['g','개','회']).map(u=>`<option value="${u}" ${food.servingUnit===u?'selected':''}>${u}</option>`).join('')}</select></label></div><div class="form-grid nutrient-fields">${[['calories','칼로리 kcal'],['carbs','탄수화물 g'],['protein','단백질 g'],['fat','지방 g']].map(([key,label])=>`<label class="field">${label}<input name="${key}" type="number" min="0" step="any" required value="${$s.esc(food[key]??0)}"></label>`).join('')}</div><button class="button">공용 음식 저장</button></form></div>`}
export function prHTML(){const all=exercisePRs(actualDB($s.db)),ms=[...new Set(all.map(x=>x.primaryMuscle).filter(Boolean))],rows=$s.prMuscle?all.filter(x=>x.primaryMuscle===$s.prMuscle):all;return `<section class="section card pr-card"><h3>종목·머신별 최고 기록</h3><p class="hint">많이 한 순서예요. 완료한 세트만 세고, kg로 바꿔 비교해요.</p>${ms.length>1?`<div class="chips pr-filter" role="group" aria-label="주동근으로 거르기"><button type="button" class="chip${$s.prMuscle?'':' active'}" data-pr-muscle="" aria-pressed="${!$s.prMuscle}">전체</button>${ms.map(m=>`<button type="button" class="chip${$s.prMuscle===m?' active':''}" data-pr-muscle="${$s.esc(m)}" aria-pressed="${$s.prMuscle===m}">${$s.esc(MUSCLE_LABELS[m]||m)}</button>`).join('')}</div>`:''}${rows.map(x=>`<div class="record"><div><strong>${$s.esc(x.name||x.exerciseName||'운동')}</strong><small>${$s.esc(($s.db.machines||[]).find(m=>m.id===x.machineId)?.model||genericMachine(x.machineId)?.name||'머신 미지정')} · ${x.sessions}일 · ${x.sets}세트${x.primaryMuscle?` · ${$s.esc(MUSCLE_LABELS[x.primaryMuscle]||'')}`:''}</small></div><span>최대 ${$s.fmt(x.maxWeight??x.maxWeightKg)} kg<br>최대 ${$s.fmt(x.maxReps)}회 · 세트 볼륨 ${$s.fmt(x.maxSetVolume)} kg<br>추정 1RM ${$s.fmt(x.best1RM??x.estimated1RM)} kg</span></div>`).join('')||'<p class="hint">완료된 기록이 없습니다.</p>'}</section>`}
export function requestRowHTML(r){return `<div class="record catalog-request-row"><div><strong>${$s.esc(r.name||r.model||r.manufacturer||r.type)}</strong><small>${$s.esc(r.type)} · ${$s.esc(r.manufacturer||'')} ${$s.esc(r.model||'')} · ${$s.esc(r.gymName||'지점 미지정')}</small><span class="req-status">${statusBadge(r.status||'pending')}</span>${r.note?`<small>${$s.esc(r.note)}</small>`:''}${r.adminNote?`<small>관리자 메모: ${$s.esc(r.adminNote)}</small>`:''}</div><div class="actions">${r.wholePhotoDataUrl&&r.nameplatePhotoDataUrl?`<button type="button" class="text-button" data-request-photo="${$s.esc(r.id)}">전체·명판 사진 보기</button>`:''}${isCatalogAdmin(cloudState.user)?`<select data-review-state="${$s.esc(r.id)}" aria-label="요청 상태"><option value="in_review">검토 중</option><option value="approved">승인</option><option value="needs_info">추가 정보</option><option value="rejected">반려</option></select><input data-review-note="${$s.esc(r.id)}" placeholder="관리자 메모" aria-label="관리자 메모"><button type="button" class="text-button" data-review-request="${$s.esc(r.id)}">상태 저장</button>`:''}</div></div>`}
export function checkinHTML(){const c=$s.db.checkins?.[$f.today()]||{};return `<form id="checkin-form" class="gap"><p class="hint">${$f.today()} · 기록 기반 제안을 위한 자가 입력입니다. 비워두면 미확인으로 표시합니다.</p>${[['sleep','수면 만족도'],['energy','전신 에너지'],['soreness','근육통 정도']].map(([k,label])=>`<label class="field">${label} (1 낮음 · 5 높음)<select name="${k}"><option value="">미입력</option>${[1,2,3,4,5].map(n=>`<option value="${n}" ${Number(c[k])===n?'selected':''}>${n}</option>`).join('')}</select></label>`).join('')}<label class="field">통증·부상 우려<select name="pain"><option value="">미확인</option><option value="false" ${c.pain===false?'selected':''}>없음</option><option value="true" ${c.pain===true?'selected':''}>있음</option></select></label><button class="button">오늘 상태 저장</button></form>`}
export function backupNudgeHTML(){if($s.DEMO||cloudState.user)return '';const n=($s.db.meals||[]).length+($s.db.workouts||[]).length+($s.db.body||[]).length;if(n<10)return '';const last=$s.lsNum('mylogue.lastBackupAt'),snooze=$s.lsNum('mylogue.backupSnoozeUntil'),now=Date.now();if(now<snooze||(last&&now-last<30*864e5))return '';return `<section class="section card backup-nudge"><h3>기록이 이 기기에만 있어요</h3><p class="hint">로그인하지 않고 쓰는 중이라, 휴대폰을 바꾸거나 브라우저 데이터를 지우면 기록이 사라질 수 있어요. ${last?`마지막 백업: ${new Date(last).toLocaleDateString('ko-KR')}`:'아직 백업한 적이 없어요'}.</p><div class="actions"><button type="button" class="button" id="backup-nudge-export">백업 파일 받기</button><button type="button" class="button secondary" id="backup-nudge-later">일주일 뒤에</button></div></section>`}
export function reviewHTML(){const c=comparePeriods(actualDB($s.db),30),w=weeklyReport(actualDB($s.db)),bodyDays=new Set($s.db.body.filter(x=>x.date>=w.from&&x.date<=w.to).map(x=>x.date)).size;return `<section class="section card"><h3>이번 주 기록과 이전 기간 비교</h3><p>수치 ${bodyDays}/7일 · 식단 완료/단식 ${w.completeDietDays}/7일 · 운동 ${w.workoutDays}/7일</p><p class="hint">식단 일부 ${w.partialDietDays}일 · 미기록 ${w.missingDietDays}일. 운동 없는 날은 자동으로 휴식으로 판단하지 않습니다.</p><p>직전 30일 대비 운동 ${c.workoutSessionsChange>0?'+':''}${c.workoutSessionsChange}회 · 기록 볼륨 ${$s.fmt(c.volumeChange)} kg</p><p class="hint">식단 평균 차이 ${$s.fmt(c.averageCaloriesChange)} kcal · 두 기간 모두 완료/단식일 기준이며 결측에 따라 비교 의미가 달라집니다. ${$s.esc(c.note)}</p></section>`}
export function recommendationHTML(){const v=$f.recommendationView();return `${(v.raw.suggestions||[]).map(x=>`<div class="record rec-sugg">${exArtHTML(x,'ex-art-md',{fallback:true})}<div><strong>${$s.esc(x.name)}</strong><small>${$s.esc(x.reason)}</small></div></div>`).join('')}<details class="rec-note"><summary>ⓘ 이 제안은 어떻게 정했나요</summary><p><b>${$s.esc(v.title)}</b> · ${$s.esc(v.reason)}</p><p class="hint">${$s.esc(v.note)}</p><p class="hint">미확인: ${$s.esc(v.raw.missing?.join(', ')||'없음')} · 오늘 상태는 자가 입력이며 실제 회복을 측정한 값이 아닙니다.</p></details><button class="button secondary" id="apply-recommendation">초안을 확인·수정</button>`}
export function loadAtlasHTML(key){const r=recommendWorkout($s.db,$f.today());return `${muscleMapHTML([],[],{key,mode:'load',loads:r.loads})}<div class="atlas-load-list">${r.loads.map(x=>`<div class="record"><strong>${$s.esc(MUSCLE_LABELS[x.muscleId]||x.muscleId)} · ${$s.esc(x.level)}</strong><small>지표 ${$s.fmt(x.score)} · 가중 세트 ${$s.fmt(x.sets)}<br>마지막 기록 ${$s.esc(x.lastDate)}</small></div>`).join('')||'<p class="hint">최근 완료 세트가 없어 부위별 부하를 판단하지 않습니다.</p>'}</div><details><summary>계산 근거와 미확인 정보</summary><p class="hint">${$s.esc(r.note)}</p><p class="hint">미확인: ${$s.esc(r.missing.join(', ')||'없음')}</p></details>`}
// 4.29.3 기준 종목이 없는 예전 운동 이름: 기록은 그대로 두고, 이름을 기준 종목에 이어 준다(그림·성장 기록)
export function unlinkedExercises(db=$s.db){const all=(db.workouts||[]).flatMap(w=>w.exercises||[]);const names=missingBases(all);const counts=new Map();for(const ex of all){const n=String(ex.name||'').trim();if(names.includes(n))counts.set(n,(counts.get(n)||0)+1)}return names.map(n=>({name:n,count:counts.get(n)||0,part:(all.find(x=>String(x.name||'').trim()===n)||{}).part||''})).sort((a,b)=>b.count-a.count)}
export function profilesHTML(){const un=unlinkedExercises(),noBase=($s.db.machines||[]).filter(m=>!machineBase(m));return `<details class="section card" id="profiles-card"><summary>내 머신·사용자 종목 관리${un.length+noBase.length?` · 이어 줄 것 ${un.length+noBase.length}개`:''}</summary>${un.length?`<h3>어떤 운동인지 아직 모르는 이름</h3><p class="hint">지난 기록은 그대로예요. 이름마다 기준 종목을 골라 주면 그림이 나오고 같은 동작 기록과 이어져요.</p>${un.map(x=>`<div class="record"><strong>${$s.esc(x.name)}</strong><small>${x.count}번 기록</small><button data-link-base="${$s.esc(x.name)}" data-link-part="${$s.esc(x.part)}">기준 종목 고르기</button></div>`).join('')}`:''}<h3>머신</h3>${($s.db.machines||[]).map(x=>`<div class="record"><strong>${$s.esc(x.name)} · ${$s.esc(x.manufacturer)} ${$s.esc(x.model)}</strong>${machineBase(x)?'':'<small class="warn">기준 종목 없음</small>'}<button data-edit-machine="${$s.esc(x.id)}">${machineBase(x)?'수정':'기준 종목 고르기'}</button></div>`).join('')||'<p class="hint">운동 입력 중 머신을 등록하세요.</p>'}<h3>나만의 종목</h3>${($s.db.customExercises||[]).map(x=>`<div class="record"><strong>${$s.esc(x.name)}</strong>${x.kind!=='cardio'&&!x.baseExerciseId&&!resolveExercise(x.name)?'<small class="warn">기준 종목 없음</small>':''}<button data-edit-custom="${$s.esc(x.id)}">수정</button></div>`).join('')||'<p class="hint">운동 도감에서 직접 등록할 수 있습니다.</p>'}</details>`}
export function wteHTML(){if($s.selectedDate!==$f.today())return '';const remain=$f.remainToday();if(!planCan('what-to-eat'))return whatToEatHTML($s.wte,remain,{locked:plusLockHTML('what-to-eat',$s.esc)});if(!foodDBReady()){loadFoodDB().then(()=>$f.render()).catch(()=>{});return whatToEatHTML($s.wte,remain,{ready:false})}const key=`${$s.wte.mood}|${$s.wte.place}|${Math.round(remain.kcal/50)}|${Math.round(remain.protein/5)}`;if($s.wte.key!==key){$s.wte.results=suggestMeals(remain,{mood:$s.wte.mood,place:$s.wte.place});$s.wte.key=key}return whatToEatHTML($s.wte,remain,{results:$s.wte.results})}
export function dietControls(){const state=dietState($s.db,$s.selectedDate);return `<section class="section card"><h3>하루 기록 상태</h3><div class="chip-row">${[['unrecorded','미기록'],['partial','일부 기록'],['complete','하루 완료'],['fasting','의도적 단식']].map(([k,v])=>`<button class="chip ${state===k?'active':''}" data-diet-state="${k}" aria-pressed="${state===k}">${v}</button>`).join('')}</div><p class="hint">평균은 하루 완료·단식일만 사용합니다. 일부 기록은 완전한 하루 섭취량으로 계산하지 않습니다.</p><div class="actions"><button class="button secondary" data-modal="meal">음식 하나 입력</button><button class="button secondary" id="copy-meals">다른 날·끼니 복사</button></div></section>`}
export function sessionControls(){return `<section class="section card session-card"><h3>작성 중인 운동</h3>${$s.savedDraft?`<p class="hint">${$s.esc($s.savedDraft.meta?.title||'운동')} · ${$s.savedDraft.exercises?.length||0}종목</p><div class="actions"><button class="button" id="resume-session">이어서 기록</button><button class="button secondary" id="discard-session">임시 기록 삭제</button></div>`:'<p class="hint">운동 중 입력은 이 기기에 임시 저장됩니다.</p>'}${$s.draftWarning?`<p role="alert">${$s.esc($s.draftWarning)}</p><button class="button secondary" id="draft-export">원본 내보내기</button>${$s.savedDraft?'':'<button class="button secondary" id="discard-session">손상 초안 초기화</button>'}`:''}</section>`}
export function coachNote(){if($s.selectedDate!==$f.today())return '';let r;try{r=analyzeCoach(actualDB($s.db),$f.today()).filter(x=>x.level!=='praise')}catch{return ''}if(!r.length)return '';const key=scopedKey('mylogue.coachNoteHidden');let hid='';try{hid=localStorage.getItem(key)||''}catch{}if(hid===$f.today())return '';const top=r.slice(0,2);return `<section class="section card coach-note${top.some(x=>x.level==='safety')?' safety':''}" aria-label="코치 노트"><div class="cn-head"><b>오늘의 코치 노트</b><button type="button" class="text-button" data-coach-note-hide>오늘은 닫기</button></div>${top.map(x=>`<p>${$s.esc(x.text)}</p>${x.source?`<details class="cn-why"><summary>근거</summary><small>${$s.esc(x.why)} · ${$s.esc(x.source)}</small></details>`:''}`).join('')}<small class="hint">참고용 안내예요. 진단이나 처방이 아니에요.</small></section>`}
export function accountChip(){const s=cloudState;if(!s.configured||(s.native&&!nativeAuthAvailable()))return '';if(!s.user)return `<button type="button" class="account-chip account-login" id="cloud-login" aria-label="Google 계정으로 로그인"><span class="account-avatar" aria-hidden="true"><svg viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round"><circle cx="12" cy="8" r="4"/><path d="M4 21c1.5-4 4.5-6 8-6s6.5 2 8 6"/></svg></span><span class="account-text"><strong>로그인</strong><small>기록 동기화</small></span></button>`;const pr=profileOf($s.db,s.user),status={pending:['승인 대기','wait'],not_applied:['신청 필요','wait'],rejected:['반려됨','bad']}[s.approval]||(s.approval==='approved'?null:['확인 중','wait']);return `<button type="button" class="account-chip" id="profile-open" aria-label="내 프로필: ${$s.esc(pr.name)}${status?', '+status[0]:''}">${avatarHTML(pr,"account-avatar",{plus:isPlus()})}<span class="account-text"><strong>${$s.esc(pr.name)}</strong>${status?`<small class="account-status ${status[1]}">${status[0]}</small>`:''}</span></button>`}
export function brandMarkHTML({done,total}){const C=2*Math.PI*21,seg=C/total,gap=total>1?4:0,arcs=Array.from({length:total},(_,i)=>`<circle cx="24" cy="24" r="21" pathLength="${C.toFixed(2)}" stroke-dasharray="${(seg-gap).toFixed(2)} ${(C-seg+gap).toFixed(2)}" stroke-dashoffset="${(-i*seg).toFixed(2)}" class="${i<done?'on':''}"/>`).join('');return `<span class="brand-mark${done>=total?' full':''}" aria-hidden="true"><svg viewBox="0 0 48 48"><defs><linearGradient id="brand-ring" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#8ce4e0"/><stop offset="1" stop-color="#b48cff"/></linearGradient></defs><g transform="rotate(-90 24 24)">${arcs}</g></svg><img src="icon.svg" alt=""></span>`}
export function chart(items,key,days=30){/* 4.17.0 다른 그래프와 같은 모양(공통 lineChart, 눌러서 값 보기) */const cutoff=new Date();cutoff.setHours(0,0,0,0);cutoff.setDate(cutoff.getDate()-days+1);const data=$s.recent(items).filter(x=>x[key]!=null&&new Date(x.date)>=cutoff).sort((a,b)=>a.date.localeCompare(b.date));if(!data.length)return '<div class="empty">아직 그래프로 표시할 기록이 없습니다.</div>';const vals=data.map(x=>x[key]),min=Math.min(...vals),max=Math.max(...vals),md=d=>`${Number(d.slice(5,7))}/${Number(d.slice(8,10))}`;return `${lineChart({vals,color:'#8ce4e0',h:130,tips:data.map(x=>`<span class="d">${md(x.date)}</span><b>${$s.fmt(x[key])}kg</b>`),dateL:md(data[0].date),dateR:md(data.at(-1).date),label:`${key==='best1RM'?'추정 최대 중량':key} 추이`})}<div class="row small muted"><span>최저 ${$s.fmt(min)}</span><span>최고 ${$s.fmt(max)}</span></div>`}
